function activateTab(e){const t=document.querySelectorAll(".gokhale-tab"),n=document.querySelectorAll(".gokhale-section");if(!t.length||!n.length)return;t.forEach(e=>e.classList.remove("active")),n.forEach(e=>e.classList.remove("active"));const o=document.querySelector(`.gokhale-tab[data-tab="${e}"]`),a=document.getElementById(e);o&&o.classList.add("active"),a&&(a.classList.add("active"),a.scrollIntoView({behavior:"smooth",block:"start"}))}function initTabNavigation(){document.querySelectorAll(".gokhale-tab").forEach(e=>{e.addEventListener("click",()=>activateTab(e.dataset.tab))});const e=window.location.hash.replace("#","");if(e){["biography","timeline","congress","social-reforms","gandhi-influence","legacy","references"].includes(e)&&activateTab(e)}}function initThemeToggle(){const e=document.getElementById("theme-toggle");if(!e)return;updateThemeIcon(localStorage.getItem("theme")||"dark"),e.addEventListener("click",()=>{const e=document.body;e.classList.contains("light-theme")?(e.classList.remove("light-theme"),localStorage.setItem("theme","dark"),updateThemeIcon("dark")):(e.classList.add("light-theme"),localStorage.setItem("theme","light"),updateThemeIcon("light"))})}function updateThemeIcon(e){const t=document.getElementById("theme-toggle");t&&(t.textContent="light"===e?"🌙":"☀️")}function initSmoothScroll(){document.querySelectorAll('a[href^="#"]').forEach(e=>{e.addEventListener("click",function(e){const t=document.querySelector(this.getAttribute("href"));t&&(e.preventDefault(),t.scrollIntoView({behavior:"smooth",block:"start"}))})})}function initMobileMenu(){const e=document.getElementById("menu-toggle"),t=document.getElementById("nav-menu");e&&t&&e.addEventListener("click",()=>{const n="true"===e.getAttribute("aria-expanded");e.setAttribute("aria-expanded",String(!n)),t.classList.toggle("active")})}function initCountUp(){const e=document.querySelectorAll(".gokhale-count");if(!e.length)return;const t=new IntersectionObserver((e,t)=>{e.forEach(e=>{if(e.isIntersecting){const n=e.target,o=parseInt(n.getAttribute("data-target"),10);if(isNaN(o))return;let a=0;const i=Math.max(1,Math.floor(o/60)),c=()=>{a+=i,a>o&&(a=o),n.textContent=a,a<o&&requestAnimationFrame(c)};c(),t.unobserve(n)}})},{threshold:.6});e.forEach(e=>t.observe(e))}document.addEventListener("DOMContentLoaded",()=>{initTabNavigation(),initThemeToggle(),initSmoothScroll(),initMobileMenu(),initCountUp()});